Object.assign(SNIP,{});PRESET_NOTES["l13"]={"Ví dụ: Tìm vị trí đầu tiên": "Mũi tên i đi từ trái sang phải và dừng ngay khi gặp x. Thử nhập 8 (tốt nhất: 1 lần so sánh), 1 hoặc 100 (xấu nhất: duyệt hết).", "Ví dụ: Vị trí cuối cùng và số lần xuất hiện": "Muốn vị trí cuối hoặc số lần thì không dừng sớm được: phải duyệt hết dãy. Bật Đoán trước để đoán giá trị của cuoi.", "Ví dụ: Dùng find và count của thư viện": "find trả về vị trí đầu tiên; không có thì trả về end(), tức chỉ số bằng a.size(). Bên trong vẫn là tìm kiếm tuần tự O(n).", "Ví dụ: Số chẵn đầu tiên lớn hơn 10": "Điều kiện tìm có thể là bất cứ thứ gì. break thoát vòng lặp ngay khi tìm thấy, giống return trong hàm."};EX_HINTS["l13"]=[["Một lần duyệt là đủ: dau chỉ gán lần đầu gặp (khi còn bằng −1), cuoi gán mỗi lần gặp.", "Đề tính chỉ số từ 1: in i + 1."], ["Tìm phần tử đầu tiên thỏa điều kiện “tổng tới đây ≥ S”. Ghi nhận lần đầu tiên rồi không ghi đè nữa.", "Tổng tới 10¹⁴: long long."], ["n số chỉ phủ được tối đa n giá trị 0..n−1, nên đáp án ≤ n. Số lớn hơn n bỏ qua.", "Đánh dấu co[x] = true, rồi tìm tuần tự ô false đầu tiên. Tránh “với mỗi k, tìm k trong dãy” vì đó là O(n²)."]];
