const PR13=[{label:"Ví dụ: Tìm vị trí đầu tiên",input:"5",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint timViTri(vector<int>& a, int x) {\n    for (int i = 0; i < (int)a.size(); i++) {\n        if (a[i] == x) return i;\n    }\n    return -1;\n}\n\nint main() {\n    vector<int> a = {8, 3, 12, 5, 3, 9, 1};\n    int x;\n    cin >> x;\n    cout << timViTri(a, x) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"vars",names:["x"]}],py:{code:"def timViTri(a, x):\n    for i in range(len(a)):\n        if a[i] == x:\n            return i\n    return -1\n\na = [8, 3, 12, 5, 3, 9, 1]\nx = int(input())\nprint(timViTri(a, x))"},cs:{code:"using System;\n\nclass Program\n{\n    static int TimViTri(int[] a, int x)\n    {\n        for (int i = 0; i < a.Length; i++)\n        {\n            if (a[i] == x) return i;\n        }\n        return -1;\n    }\n\n    static void Main()\n    {\n        int[] a = { 8, 3, 12, 5, 3, 9, 1 };\n        int x = int.Parse(Console.ReadLine());\n        Console.WriteLine(TimViTri(a, x));\n    }\n}"}},{label:"Ví dụ: Vị trí cuối cùng và số lần xuất hiện",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 7, 4, 1, 4, 9};\n    int x = 4, cuoi = -1, dem = 0;\n    for (int i = 0; i < (int)a.size(); i++) {\n        if (a[i] == x) {\n            cuoi = i;\n            dem++;\n        }\n    }\n    cout << \"Cuoi cung o \" << cuoi << \", xuat hien \" << dem << \" lan\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","cuoi"]},{type:"vars",names:["cuoi","dem"]}],predict:[{line:10,v:"i",q:"cuoi sẽ trỏ vào ô nào? (bấm một ô)"}],py:{code:"a = [4, 7, 4, 1, 4, 9]\nx = 4\ncuoi = -1\ndem = 0\nfor i in range(len(a)):\n    if a[i] == x:\n        cuoi = i\n        dem += 1\nprint(\"Cuoi cung o\", cuoi, \", xuat hien\", dem, \"lan\")",predict:[{line:7,v:"i",q:"cuoi sẽ trỏ vào ô nào? (bấm một ô)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 7, 4, 1, 4, 9 };\n        int x = 4, cuoi = -1, dem = 0;\n        for (int i = 0; i < a.Length; i++)\n        {\n            if (a[i] == x)\n            {\n                cuoi = i;\n                dem++;\n            }\n        }\n        Console.WriteLine(\"Cuoi cung o \" + cuoi + \", xuat hien \" + dem + \" lan\");\n    }\n}",predict:[{line:13,v:"i",q:"cuoi sẽ trỏ vào ô nào? (bấm một ô)"}]}},{label:"Ví dụ: Dùng find và count của thư viện",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {8, 3, 12, 5, 3, 9};\n    int vt = find(a.begin(), a.end(), 3) - a.begin();\n    cout << \"3 o vi tri \" << vt << \"\\n\";\n    int k = find(a.begin(), a.end(), 7) - a.begin();\n    if (k == (int)a.size()) cout << \"Khong co 7\\n\";\n    cout << \"So lan 3 xuat hien: \" << count(a.begin(), a.end(), 3) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["vt","k"]}],py:{label:"Ví dụ: Dùng in, index và count",code:"a = [8, 3, 12, 5, 3, 9]\nvt = a.index(3)\nprint(\"3 o vi tri\", vt)\nk = 7 in a\nif not k:\n    print(\"Khong co 7\")\nprint(\"So lan 3 xuat hien:\", a.count(3))",note:"x in a, a.index(x), a.count(x) đều là tìm kiếm tuần tự O(n) bên trong. a.index(x) báo lỗi ValueError nếu không có x, nên kiểm tra x in a trước."},cs:{label:"Ví dụ: Dùng Array.IndexOf và Count của thư viện",code:"using System;\nusing System.Linq;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 8, 3, 12, 5, 3, 9 };\n        int vt = Array.IndexOf(a, 3);\n        Console.WriteLine(\"3 o vi tri \" + vt);\n        int k = Array.IndexOf(a, 7);\n        if (k == -1) Console.WriteLine(\"Khong co 7\");\n        Console.WriteLine(\"So lan 3 xuat hien: \" + a.Count(v => v == 3));\n    }\n}",note:"Array.IndexOf(a, x) tìm tuần tự từ đầu, trả về −1 nếu không có. a.Count(v => v == 3) (cần using System.Linq) duyệt cả mảng và đếm phần tử thỏa điều kiện. Cả hai đều O(n)."}},{label:"Ví dụ: Số chẵn đầu tiên lớn hơn 10",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {7, 14, 3, 8, 22, 5, 12};\n    int vt = -1;\n    for (int i = 0; i < (int)a.size(); i++) {\n        if (a[i] % 2 == 0 && a[i] > 10) {\n            vt = i;\n            break;\n        }\n    }\n    if (vt == -1) cout << \"Khong co\\n\";\n    else cout << \"a[\" << vt << \"] = \" << a[vt] << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"]}],py:{code:"a = [7, 14, 3, 8, 22, 5, 12]\nvt = -1\nfor i in range(len(a)):\n    if a[i] % 2 == 0 and a[i] > 10:\n        vt = i\n        break\nif vt == -1:\n    print(\"Khong co\")\nelse:\n    print(f\"a[{vt}] = {a[vt]}\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 7, 14, 3, 8, 22, 5, 12 };\n        int vt = -1;\n        for (int i = 0; i < a.Length; i++)\n        {\n            if (a[i] % 2 == 0 && a[i] > 10)\n            {\n                vt = i;\n                break;\n            }\n        }\n        if (vt == -1) Console.WriteLine(\"Khong co\");\n        else Console.WriteLine(\"a[\" + vt + \"] = \" + a[vt]);\n    }\n}"}}];
