makeEx2(document.getElementById("ex-l13"),sim13,[{t:"Vị trí đầu và cuối",d:"Đầu vào: n (1 ≤ n ≤ 10^5), dòng sau n số nguyên, dòng cuối số x. Chỉ số tính từ 1. Đầu ra: vị trí đầu tiên và vị trí cuối cùng của x trong dãy, cách nhau một khoảng trắng; nếu không có x, in -1.",tests:[{in:"6\n4 7 4 1 4 9\n4",out:"1 5"},{in:"3\n1 2 3\n5",out:"-1"},{in:"1\n8\n8",out:"1 1"},{in:"5\n2 1 1 1 2\n2",out:"1 5"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // đọc dãy, đọc x, rồi tìm\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%(n+7)).join(" ")+"\n"+(n+3),ns:[500,2000,8000],need:"n",limit:n=>30*n+200,why:"Một lần duyệt O(n) là đủ."},py:{start:"n = int(input())\na = list(map(int, input().split()))\nx = int(input())\n# tìm vị trí đầu và cuối (đếm từ 1)",hints:["Một lần duyệt là đủ: dau chỉ gán lần đầu gặp (khi còn bằng −1), cuoi gán mỗi lần gặp.","Đề tính chỉ số từ 1: in i + 1."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int x = int.Parse(Console.ReadLine());\n        // tìm vị trí đầu tiên và cuối cùng (tính từ 1)\n    }\n}",hints:["Một lần duyệt là đủ: dau chỉ gán lần đầu gặp (khi còn bằng −1), cuoi gán mỗi lần gặp.","Đề tính chỉ số từ 1: in i + 1."]}},{t:"Ngày đủ tiền",d:"Đầu vào: n và S (1 ≤ n ≤ 10^5, 1 ≤ S ≤ 10^14), rồi n số nguyên dương: số tiền tiết kiệm được mỗi ngày (≤ 10^9). Đầu ra: ngày đầu tiên (tính từ 1) mà tổng tiền tiết kiệm từ ngày 1 tới ngày đó đạt ít nhất S; nếu không bao giờ đạt, in -1.",tests:[{in:"5 10\n3 2 4 1 5",out:"4"},{in:"3 100\n10 20 30",out:"-1"},{in:"1 1\n1",out:"1"},{in:"4 6\n6 1 1 1",out:"1"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    long long S;\n    cin >> n >> S;\n    // cộng dồn và dừng ngay khi đủ\n    return 0;\n}",perf:{gen:n=>n+" "+(n*3)+"\n"+Array.from({length:n},(_,i)=>1+(i*37)%7).join(" "),ns:[500,2000,8000],need:"n",limit:n=>25*n+200,why:"Tính lại tổng từ ngày 1 cho mỗi ngày là O(n²). Cộng dồn trong lúc duyệt chỉ cần O(n)."},py:{start:"n, S = map(int, input().split())\na = list(map(int, input().split()))\n# cộng dồn và dừng ngay khi đủ",hints:["Tìm phần tử đầu tiên thỏa điều kiện “tổng tới đây ≥ S”, rồi break.","Tính lại sum(a[:i]) cho mỗi ngày là O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        long S = long.Parse(t[1]);\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        // cộng dồn và dừng ngay khi đủ\n    }\n}",hints:["Tìm phần tử đầu tiên thỏa điều kiện “tổng tới đây ≥ S”, rồi break.","Tổng tới 10¹⁴: long."]}},{t:"Số tự nhiên nhỏ nhất bị thiếu",d:"Đầu vào: n (1 ≤ n ≤ 10^5), rồi n số nguyên không âm (≤ 10^9). Đầu ra: số tự nhiên nhỏ nhất (0, 1, 2, …) không có trong dãy.",tests:[{in:"5\n3 0 1 5 2",out:"4"},{in:"3\n1 2 3",out:"0"},{in:"4\n0 1 2 3",out:"4"},{in:"1\n1000000000",out:"0"},{in:"6\n0 0 1 1 3 3",out:"2"}],start:"#include <iostream>\nusing namespace std;\n\nbool co[100002];\n\nint main() {\n    int n;\n    cin >> n;\n    // đáp án không vượt quá n: chỉ cần đánh dấu các số từ 0 tới n\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i===n-1?n+5:i).join(" "),ns:[500,2000,8000],need:"n",limit:n=>25*n+200,why:"Với mỗi k lại tìm tuần tự trong dãy là O(n²). Đánh dấu một lần rồi quét mảng đánh dấu chỉ O(n)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\nco = [False] * (n + 2)\n# đáp án không vượt quá n: chỉ cần đánh dấu các số từ 0 tới n",hints:["n số chỉ phủ được tối đa n giá trị 0..n−1, nên đáp án ≤ n. Số lớn hơn n bỏ qua.","Đánh dấu co[x] = True, rồi tìm tuần tự ô False đầu tiên. Tránh “với mỗi k, kiểm tra k in a” vì đó là O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        bool[] co = new bool[n + 2];\n        // đáp án không vượt quá n: chỉ cần đánh dấu các số từ 0 tới n\n    }\n}",hints:["n số chỉ phủ được tối đa n giá trị 0..n−1, nên đáp án ≤ n. Số lớn hơn n bỏ qua.","Đánh dấu co[x] = true, rồi tìm tuần tự ô false đầu tiên. Tránh “với mỗi k, tìm k trong dãy” vì đó là O(n²)."]}}]);

